[IO.File]::WriteAllText((Join-Path $PWD 'with-surl.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Starts surl on a free port to serve <directory>, runs <command> with SURL_URL set to the`n# server's URL, and stops surl however the script ends: the command passing or failing, or`n# the script itself interrupted. Exits with the command's exit code.`n# Usage: sh with-surl.sh <directory> <command> [<argument>...]`ndir=`$1; shift`n: > surl.out`nsurl --directory `"`$dir`" http://127.0.0.1:0/ > surl.out 2> surl.err &`nsurl_pid=`$!`ncommand_pid=`n`nstop() {   # on any exit: end the command if it still runs, then stop surl and wait for it`n  status=`$?`n  [ -z `"`$command_pid`" ] || kill `"`$command_pid`" 2>/dev/null`n  kill `"`$surl_pid`" 2>/dev/null`n  wait `"`$surl_pid`"`n  echo `"stopped surl: exit `$?`" >&2`n  exit `"`$status`"`n}`ntrap stop EXIT`ntrap 'exit 130' INT`ntrap 'exit 143' TERM`n`n# surl writes `"Listening on <url>`" once it has bound. If it exits first, it refused to`n# start: show why and pass its exit code on.`ntries=0`nuntil grep -q '^Listening on ' surl.out; do`n  if ! kill -0 `"`$surl_pid`" 2>/dev/null; then`n    wait `"`$surl_pid`"; status=`$?`n    cat surl.err >&2`n    trap - EXIT`n    exit `"`$status`"`n  fi`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -ge 100 ]; then echo `"surl wrote no Listening on line`" >&2; exit 1; fi`n  sleep 0.1`ndone`nSURL_URL=`$(sed -n 's|^Listening on ||p' surl.out)`nexport SURL_URL`n`n# Run the command in the background and wait for it, so a signal to this script is acted on`n# at once rather than when the command ends.`n`"`$@`" &`ncommand_pid=`$!`nwait `"`$command_pid`"`nstatus=`$?`ncommand_pid=`nexit `"`$status`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'tests.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Stands in for the tests: fetches one path from the server with-surl.sh started.`n# Usage: sh tests.sh <path>`ncurl -fsS `"`${SURL_URL}`$1`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'interrupt.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Stands in for a CI runner cancelling the job: starts with-surl.sh with a command that would`n# run for a minute, sends the script SIGTERM a second after surl listens, when the command is`n# running, then checks surl is gone. It gives up after 10 s if surl never listens.`nrm -f surl.out`nsh with-surl.sh site sleep 60 2> interrupt.err &`nscript=`$!`ntries=0`nuntil grep -q '^Listening on ' surl.out 2>/dev/null; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -ge 100 ]; then echo `"surl wrote no Listening on line`"; kill `"`$script`"; exit 1; fi`n  sleep 0.1`ndone`nsleep 1`nkill `"`$script`"`nwait `"`$script`"`necho `"with-surl.sh: exit `$?`"`nsh check-stopped.sh`n")
[IO.File]::WriteAllText((Join-Path $PWD 'check-stopped.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Tries the URL of the last surl that with-surl.sh started; curl exit 7 means nothing listens.`ncurl -s -o /dev/null `"`$(sed -n 's|^Listening on ||p' surl.out)`"`necho `"after: curl exit `$?`"`n")
